# Stateless Strategy registry + Factory-ordered Decorator composition (Python)
from typing import Callable, Protocol

class Notifier(Protocol):
    def send(self, msg: str) -> None: ...

class RetryingNotifier:
    def __init__(self, inner: Notifier, attempts: int = 3):  # Canonical wrapper
        self._inner, self._attempts = inner, attempts
    def send(self, msg: str) -> None:
        for i in range(self._attempts):
            try: return self._inner.send(msg)
            except TimeoutError:
                if i == self._attempts - 1: raise

